Think: Normalize extracted lines by trimming and standardizing whitespace, removing trailing punctuation from the error code and message fields, and write normalized output files to the "normalized" folder with the same filenames.

Act: bash

```bash
awk -F':' '{
  n=split(FILENAME,a,"/"); fname=a[n];
  # reconstruct message in case it contains extra colons
  ts=$1; code=$2; msg=$3;
  for(i=4;i<=NF;i++) msg = msg ":" $i;
  # trim leading/trailing whitespace
  gsub(/^[ \t]+/,"",ts); gsub(/[ \t]+$/,"",ts);
  gsub(/^[ \t]+/,"",code); gsub(/[ \t]+$/,"",code);
  gsub(/^[ \t]+/,"",msg); gsub(/[ \t]+$/,"",msg);
  # collapse internal whitespace in message
  gsub(/[[:space:]]+/," ",msg);
  # remove trailing punctuation from code and message
  sub(/[[:punct:]]+$/,"",code);
  sub(/[[:punct:]]+$/,"",msg);
  print ts ":" code ":" msg > ("normalized/" fname)
}' extracted_lines/*
```

