Think: Compare recorded attributes in temp_workspace_check/attributes.txt with current stat values; write mismatches to consistency_issues.txt and matches to consistent_paths.txt.

Act: bash

```bash
awk '{
  size=$1; mtime=$2;
  # path may contain spaces; get from the third field onward
  path=substr($0, index($0,$3));
  cmd = "stat -c \"%s %Y %n\" \"" path "\" 2>/dev/null";
  cmd | getline cur; close(cmd);
  if(cur=="") {
    print path " MISSING_OR_INACCESSIBLE" >> "temp_workspace_check/consistency_issues.txt";
  } else {
    split(cur,a," ");
    if(a[1]!=size || a[2]!=mtime) {
      print path " RECORDED:" size ":" mtime " CURRENT:" a[1] ":" a[2] >> "temp_workspace_check/consistency_issues.txt";
    } else {
      print path >> "temp_workspace_check/consistent_paths.txt";
    }
  }
}' temp_workspace_check/attributes.txt
```

